schemas.schema-01-systematic.prisma:
/// Platform channel management defining different marketplace environments,
/// configurations, and business rules.
///
/// Channels represent distinct platform instances with unique settings,
/// policies, and user experiences. Each channel can have different
/// commission structures, supported countries, and operational
/// configurations while sharing the same underlying infrastructure.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique channel identifier used for routing and configuration.
  code String

  /// Channel display name shown to users across the platform.
  name String

  /// Detailed description of channel purpose and business model.
  description String?

  /// Channel operational status: active, inactive, maintenance, suspended.
  status String

  /// Primary currency for transactions in this channel (ISO 4217 code).
  currency String

  /// Primary country code for this channel (ISO 3166-1 alpha-2).
  country_code String?

  /// Primary language for this channel (ISO 639-1).
  language String

  /// Default commission percentage charged by platform (0-100%).
  commission_rate Float @db.DoublePrecision

  /// Minimum order amount required for checkout in this channel.
  minimum_order_value Float @db.DoublePrecision

  /// Whether tax calculation is enabled for this channel.
  tax_enabled Boolean

  /// Channel creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_sections shopping_mall_sections[]
  shopping_mall_configurations shopping_mall_configurations[]
  shopping_mall_sales shopping_mall_sales[]

  @@unique([code])
  @@index([status])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Channel section organization providing hierarchical navigation and
/// content distribution within marketplace channels.
///
/// Sections organize content within channels through hierarchical
/// categorization, creating intuitive navigation for customers while
/// enabling flexible merchandising and content management strategies per
/// channel.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Channel's {@link shopping_mall_channels.id}
  shopping_mall_channel_id String @db.Uuid

  /// Unique section identifier within the channel.
  code String

  /// Section display name shown to users.
  name String

  /// Detailed description of section content and purpose.
  description String?

  /// Hierarchy level for nested sections (0 for top-level).
  level Int @db.Integer

  /// Parent section reference for nested hierarchies.
  parent_id String? @db.Uuid

  /// Display order for sections within the same level.
  sort_order Int @db.Integer

  /// Section status: active, inactive, hidden.
  status String

  /// Whether section appears in featured navigation.
  is_featured Boolean

  /// Section creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel shopping_mall_channels @relation(fields: [shopping_mall_channel_id], references: [id], onDelete: Cascade)

  shopping_mall_sales shopping_mall_sales[]
  shopping_mall_articles shopping_mall_articles[]
  shopping_mall_bbs_posts shopping_mall_bbs_posts[]

  @@unique([shopping_mall_channel_id, code])
  @@index([shopping_mall_channel_id, parent_id])
  @@index([status])
  @@index([level, sort_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Platform-wide configuration management providing centralized settings and
/// parameters for system-wide functionality.
///
/// Configuration options control operational behavior, feature toggles,
/// security settings, and business rules that apply across all marketplace
/// channels and sections.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Channel's {@link shopping_mall_channels.id} (nullable for global configs).
  shopping_mall_channel_id String? @db.Uuid

  /// Configuration key (namespace.value format).
  key String

  /// Configuration value (string representing JSON, text, or data).
  value String

  /// Data type: string, number, boolean, json, text, file.
  type String

  /// Configuration purpose and usage description.
  description String?

  /// Configuration category: security, features, business, technical.
  category String

  /// Scope: global, channel, section, user.
  scope String

  /// Whether the value is encrypted at rest.
  is_encrypted Boolean

  /// Whether channel sections can override this setting.
  is_overridable Boolean

  /// Whether configuration appears in admin interfaces.
  is_visible Boolean

  /// JSON rules for value validation.
  validation_rules String?

  /// Configuration creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel shopping_mall_channels? @relation(fields: [shopping_mall_channel_id], references: [id], onDelete: Cascade)

  @@unique([key, shopping_mall_channel_id])
  @@index([category, scope])
  @@index([shopping_mall_channel_id])
  @@index([key])
  @@index([is_encrypted])
  @@index([value(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Customer accounts for the shopping mall platform including personal
/// information, contact details, and account settings for buyers across the
/// marketplace.
///
/// Customers can browse products, make purchases, manage addresses and
/// payment methods, track orders, and interact with sellers. Each customer
/// account is verified through email confirmation and maintains
/// comprehensive profile information for personalized shopping experiences.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer email address used for login and communications. Must be unique
  /// across all customer accounts.
  email String

  /// Encrypted password hash for secure authentication using bcrypt with
  /// minimum security standards.
  password_hash String

  /// Customer's full name for account identification and shipping purposes.
  name String

  /// Customer's phone number with international format support for
  /// verification and delivery coordination.
  phone_number String?

  /// Email verification status. Customers must verify email within 7 days of
  /// registration.
  is_verified Boolean

  /// Account status (active|inactive|suspended) for security and business rule
  /// enforcement.
  status String

  /// Account creation timestamp for audit trail and time-based analytics.
  created_at DateTime @db.Timestamptz

  /// Last account update timestamp for tracking account modifications and
  /// maintenance.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for account deactivation and potential recovery.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_customer_sessions shopping_mall_customer_sessions[]
  shopping_mall_cart_of_customers shopping_mall_cart_of_customers[]
  shopping_mall_orders shopping_mall_orders[]
  shopping_mall_coupon_usages shopping_mall_coupon_usages[]
  shopping_mall_coin_transactions shopping_mall_coin_transactions[]
  shopping_mall_mileages shopping_mall_mileages?
  shopping_mall_coin_wallets_of_customers shopping_mall_coin_wallets_of_customers?
  shopping_mall_inquiries shopping_mall_inquiries[]
  shopping_mall_tickets shopping_mall_tickets[]
  shopping_mall_favorites shopping_mall_favorites[]
  shopping_mall_wishlists shopping_mall_wishlists[]
  shopping_mall_bookmarks shopping_mall_bookmarks[]
  shopping_mall_articles shopping_mall_articles[]
  shopping_mall_bbs_posts shopping_mall_bbs_posts[]
  shopping_mall_comments shopping_mall_comments[]

  @@unique([email])
  @@index([status, is_verified])
  @@index([created_at])
}

/// Verified business sellers on the shopping mall platform including
/// business information, tax details, and marketplace settings for vendors
/// managing their stores.
///
/// Sellers undergo a comprehensive verification process including business
/// registration validation, tax identification verification, and bank
/// account confirmation. Once approved, sellers can manage product catalogs,
/// process orders, track performance, and receive platform analytics to
/// optimize their marketplace operations.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller business email used for login and business communications.
  email String

  /// Encrypted password hash for secure authentication.
  password_hash String

  /// Official registered business name as shown to customers and for tax
  /// purposes.
  business_name String

  /// Tax identification number (TIN/EIN) verified against government databases.
  tax_id String

  /// Business contact phone number for customer service and verification.
  phone_number String

  /// Registered business address for verification and correspondence.
  business_address String

  /// Bank account verification status for payment processing.
  bank_account_verified Boolean

  /// Business verification status approved by platform administrators.
  is_verified Boolean

  /// Account status (active|inactive|suspended|pending_review).
  status String

  /// Verification and account creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last account update for business information changes.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for account management.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_seller_sessions shopping_mall_seller_sessions[]
  shopping_mall_order_items shopping_mall_order_items[]
  shopping_mall_order_fulfillments shopping_mall_order_fulfillments[]
  shopping_mall_coupons shopping_mall_coupons[]
  shopping_mall_coupon_usages shopping_mall_coupon_usages[]
  shopping_mall_promotions shopping_mall_promotions[]
  shopping_mall_coin_transactions shopping_mall_coin_transactions[]
  shopping_mall_coin_wallets_of_sellers shopping_mall_coin_wallets_of_sellers?

  @@unique([email])
  @@unique([tax_id])
  @@index([status, is_verified])
  @@index([created_at])
}

/// Delivery courier partners integrated with the shopping mall platform
/// including business credentials and delivery management capabilities.
///
/// Couriers handle package pickup and delivery across the marketplace with
/// real-time tracking coordination and performance monitoring. Each courier
/// requires business registration, insurance verification, and vehicle
/// registration validation before processing delivery orders.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_couriers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Courier business email for authentication and communications.
  email String

  /// Encrypted password hash for secure courier login.
  password_hash String

  /// Registered courier business name for customer communications.
  business_name String

  /// Business tax identification number for verification and payouts.
  tax_id String

  /// Courier control center contact number for delivery coordination.
  phone_number String

  /// Geographic region coverage areas for delivery assignment.
  coverage_area String

  /// Business verification status approved by platform administrators.
  is_verified Boolean

  /// Operational status (active|inactive|suspended|pending_review).
  status String

  /// Courier partner registration timestamp.
  created_at DateTime @db.Timestamptz

  /// Last account update for business information.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for courier management.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_courier_sessions shopping_mall_courier_sessions[]
  shopping_mall_order_fulfillments shopping_mall_order_fulfillments[]

  @@unique([email])
  @@unique([tax_id])
  @@index([status, is_verified])
  @@index([created_at])
}

/// Platform administrative accounts with comprehensive oversight
/// capabilities for managing all platform operations including seller
/// verification, dispute resolution, and system administration.
///
/// Administrators have unrestricted access to platform-wide analytics, user
/// management functions, policy enforcement, and operational oversight. Each
/// administrator undergoes thorough background verification and
/// role-specific training before platform access is granted.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_administrators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Administrator email address for platform management and authentication.
  email String

  /// Encrypted password hash for secure administrator login.
  password_hash String

  /// Administrator's full name for identification and audit trail purposes.
  name String

  /// Admin contact number for two-factor authentication and emergency access.
  phone_number String

  /// Administrative role (super_admin|support|content_moderator|financial)
  role String

  /// Administrative verification through two-factor authentication setup.
  is_verified Boolean

  /// Account status (active|inactive) with immediate effect on platform access.
  status String

  /// Administrator account creation timestamp for audit purposes.
  created_at DateTime @db.Timestamptz

  /// Last account update for role or access changes.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for administrative account management.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_administrator_sessions shopping_mall_administrator_sessions[]
  shopping_mall_coin_wallets_of_administrators shopping_mall_coin_wallets_of_administrators?

  @@unique([email])
  @@index([role, status])
  @@index([created_at])
}

/// Temporary guest accounts for non-authenticated visitors browsing the
/// shopping mall platform without creating permanent accounts.
///
/// Guests can browse products, add items to cart, and view seller
/// information but cannot complete purchases or access full account
/// features. Guest sessions are maintained through temporary identifiers and
/// browser storage mechanisms.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique session identifier for temporary guest tracking across browser
  /// sessions.
  session_id String

  /// Visitor IP address for session management and temporary cart storage.
  ip_address String

  /// Browser user agent information for compatibility and tracking purposes.
  user_agent String

  /// Timestamp of the most recent guest activity for session timeout
  /// management.
  last_activity_at DateTime @db.Timestamptz

  /// Guest session creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Session expiration timestamp - guest sessions auto-expire after 60
  /// minutes.
  expires_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_carts shopping_mall_carts[]
  shopping_mall_cart_of_guests shopping_mall_cart_of_guests[]

  @@unique([session_id])
  @@index([expires_at])
  @@index([last_activity_at])
}

/// Active customer login sessions providing secure authentication
